inline BackgroundCache& cachedBackground(HWND w,HDC source){RECT r{};GetClientRect(w,&r);auto& ptr=backgroundCache[w];if(!ptr)ptr=std::make_unique<BackgroundCache>();auto& cache=*ptr;if(cache.dc&&cache.width==r.right&&cache.height==r.bottom&&cache.dpi==windowDpi(w))return cache;cache.clear();cache.width=std::max(1,int(r.right));cache.height=std::max(1,int(r.bottom));cache.dpi=windowDpi(w);cache.dc=CreateCompatibleDC(source);cache.bitmap=CreateCompatibleBitmap(source,cache.width,cache.height);cache.old=SelectObject(cache.dc,cache.bitmap);Gdiplus::Graphics g(cache.dc);g.SetInterpolationMode(Gdiplus::InterpolationModeHighQualityBicubic);Gdiplus::SolidBrush black(Gdiplus::Color(255,0,0,0));g.FillRectangle(&black,0,0,cache.width,cache.height);int top=px(w,56);if(backdrop&&r.bottom>top){auto& im=*backdrop->image;double factor=std::min(double(r.right)/im.GetWidth(),double(r.bottom-top)/im.GetHeight());int width=int(im.GetWidth()*factor),height=int(im.GetHeight()*factor);g.DrawImage(&im,(r.right-width)/2,top+(r.bottom-top-height)/2,width,height);Gdiplus::SolidBrush shade(Gdiplus::Color(185,4,12,22));int margin=px(w,20);g.FillRectangle(&shade,margin,top+px(w,12),std::max(0,int(r.right)-margin*2),std::max(0,int(r.bottom)-top-px(w,24)));}return cache;}
