    case WM_ERASEBKGND:result=1;return true;
    case WM_PRINTCLIENT:paintFrame(w,reinterpret_cast<HDC>(a));result=0;return true;
    case WM_PAINT:{PAINTSTRUCT paint{};auto dc=BeginPaint(w,&paint);paintFrame(w,dc);EndPaint(w,&paint);result=0;return true;}
    case WM_NCMOUSEMOVE:{int hit=int(a);if(hit>=101&&hit<=103){infoHoverIndex=hit-101;for(int i=0;i<3;++i){auto rr=infoRect(w,i);InvalidateRect(w,&rr,FALSE);}}else if(hit<101)infoHoverIndex=-1;chromeHover(w,hit);TRACKMOUSEEVENT track{sizeof track,TME_LEAVE|TME_NONCLIENT,w,0};TrackMouseEvent(&track);result=0;return true;}
    case WM_NCMOUSELEAVE:case WM_MOUSELEAVE:infoHoverIndex=-1;chromeHover(w,0);result=0;return true;
    case WM_MOUSEMOVE:if(GetPropW(w,L"SMA.Pressed")){POINT p{GET_X_LPARAM(b),GET_Y_LPARAM(b)};chromeHover(w,chromeHit(w,p));}else chromeHover(w,0);break;
    case WM_TIMER:if(a==hoverTimer){result=0;return true;}break;
    case WM_NCLBUTTONDOWN:if(a>=101&&a<=103){toggleInfoBox(w,int(a)-101);result=0;return true;}if(a==HTCLOSE||a==HTMINBUTTON||a==HTMAXBUTTON){SetPropW(w,L"SMA.Pressed",reinterpret_cast<HANDLE>(a));SetCapture(w);result=0;return true;}break;
