    case WM_CAPTURECHANGED:RemovePropW(w,L"SMA.Pressed");break;
    case WM_GETMINMAXINFO:if(fullChrome(w)){auto monitor=MonitorFromWindow(w,MONITOR_DEFAULTTONEAREST);MONITORINFO info{sizeof info,{},{},0};GetMonitorInfoW(monitor,&info);auto mm=reinterpret_cast<MINMAXINFO*>(b);mm->ptMaxPosition={info.rcWork.left-info.rcMonitor.left,info.rcWork.top-info.rcMonitor.top};mm->ptMaxSize={info.rcWork.right-info.rcWork.left,info.rcWork.bottom-info.rcWork.top};mm->ptMinTrackSize={std::min(px(w,840),int(mm->ptMaxSize.x)),std::min(px(w,580),int(mm->ptMaxSize.y))};result=0;return true;}break;
