inline void drawButton(const DRAWITEMSTRUCT& source){if(source.CtlType==ODT_MENU){renderButton(source);return;}auto item=source;int width=std::max(1,int(source.rcItem.right-source.rcItem.left)),height=std::max(1,int(source.rcItem.bottom-source.rcItem.top));auto dc=CreateCompatibleDC(source.hDC);auto bitmap=CreateCompatibleBitmap(source.hDC,width,height);auto old=SelectObject(dc,bitmap);item.hDC=dc;item.rcItem={0,0,width,height};renderButton(item);BitBlt(source.hDC,source.rcItem.left,source.rcItem.top,width,height,dc,0,0,SRCCOPY);SelectObject(dc,old);DeleteObject(bitmap);DeleteDC(dc);}
inline void refreshFonts(HWND w){EnumChildWindows(w,[](HWND c,LPARAM)->BOOL{widgetFont(c);return TRUE;},0);}
inline int languageMenu(HWND w,HWND button){auto menu=CreatePopupMenu();int i=0;for(auto text:{L"简体中文",L"English",L"日本語"}){AppendMenuW(menu,MF_OWNERDRAW|(language==i?MF_CHECKED:0),500+i,text);++i;}RECT r{};GetWindowRect(button,&r);TPMPARAMS params{};params.cbSize=sizeof params;params.rcExclude=r;if(GetMenuItemCount(menu)!=3){DestroyMenu(menu);throw Fault("languageMenu");}int selected=int(TrackPopupMenuEx(menu,TPM_RETURNCMD|TPM_RIGHTALIGN|TPM_TOPALIGN,r.right,r.bottom,w,&params));DestroyMenu(menu);return selected>=500&&selected<=502?selected-500:-1;}
